import { test } from '@playwright/test';

/**
 * Temporary probe (NOT a delivered check): measures how the full-render grid
 * behaves as worksheet dimensions grow, to inform the row/col cap ruling.
 */

const COLS = 26;
const ROWS = [6, 200, 500, 1000, 2000, 5000, 10000];

test('render cost vs row count', async ({ page, request }) => {
  for (const rows of ROWS) {
    const res = await request.put(
      '/api/workbooks/seed-q3-sales/worksheets/seed-q3-sales-sheet1/state',
      { data: { rowCount: rows, colCount: COLS } },
    );
    if (res.status() !== 200) {
      console.log(`rows=${rows} state import failed: ${res.status()} ${await res.text()}`);
      continue;
    }
    const started = Date.now();
    await page.goto('/workbook/seed-q3-sales', { waitUntil: 'commit' });
    let committed = -1;
    let rendered = -1;
    try {
      await page.waitForFunction(
        (n) => document.querySelectorAll('[role="rowheader"]').length === n,
        rows,
        { timeout: 120_000 },
      );
      rendered = Date.now() - started;
    } catch {
      rendered = -1;
    }
    committed = Date.now() - started;
    const domNodes =
      rendered >= 0
        ? await page.evaluate(() => document.querySelectorAll('*').length)
        : -1;
    console.log(
      `PROBE rows=${rows} cols=${COLS} cells=${rows * COLS} commit+firstRenderMs=${rendered} domNodes=${domNodes} totalMs=${committed}`,
    );
  }
});

